if(!exists('validate_source_lineage',mode='function'))library(creditratingsystem)
record<-function(identity,weight,amount)list(record_id=identity,join_key='household',weight=weight,amounts=list(balance=amount));hash<-function(letter)paste(rep(letter,64),collapse='');node<-function(identity,kind,records,letter){n<-list(node_id=identity,kind=kind,schema_version='1',vintage='2024-01',revision='0',transformation_version=if(kind=='SOURCE')'identity'else'join-v1',content_hash=hash(letter),observed_at='2024-01-01',available_at='2024-01-02',records=records);if(kind=='SOURCE'){n$source_id<-identity;n$semantic_role<-'FEATURE'};n};nodes<-list(node('left','SOURCE',list(record('l',1,100)),'a'),node('right','SOURCE',list(record('r0',1,0),record('r1',1,0)),'b'),node('out','FEATURE',list(record('o0',.5,50),record('o1',.5,50)),'c'));edges<-list(list(parent_id='left',child_id='out'),list(parent_id='right',child_id='out'));joins<-list(list(join_id='j',left_node_id='left',right_node_id='right',output_node_id='out',cardinality='one_to_many',join_type='inner',weight_contract='LEFT_WEIGHT_ALLOCATION',amount_origin='LEFT',mapping=lapply(0:1,function(i)list(output_id=paste0('o',i),left_id='l',right_id=paste0('r',i),allocation_weight=.5)),excluded_left_ids=list(),unmatched_right_ids=list()));recs<-lapply(nodes,function(n)list(reconciliation_id=paste0('rec-',n$node_id),node_id=n$node_id,reference='independent-input-ledger',expected_record_ids=lapply(n$records,function(r)r$record_id),expected_total_weight=if(n$node_id=='right')2 else 1,expected_amounts=list(balance=if(n$node_id=='right')0 else 100)));uses<-list(list(use_id='u',node_id='out',purpose='FEATURE',as_of='2024-01-02',known_at='2024-01-02',source_snapshot_hashes=list(left=hash('a'),right=hash('b'))));contract<-list(contract_id='lineage',version='1',reference='declared-left-allocation',amount_fields=list(balance='EUR'),absolute_tolerance=1e-12,relative_tolerance=1e-12,required_node_ids=c('left','right','out'),required_use_ids='u',required_join_ids='j');run<-function()validate_source_lineage(nodes,edges,joins,recs,uses,contract)$value;r<-run();stopifnot(r$decision$status=='PASS',r$node_totals$out$total_weight==1,r$node_totals$out$amounts$balance==100,r$join_findings[[1]]$allocated_left_weights$l==1,identical(unlist(r$topological_order),c('left','right','out')));for(i in 1:2){nodes[[3]]$records[[i]]$weight<-1;nodes[[3]]$records[[i]]$amounts$balance<-100};joins[[1]]$cardinality<-'one_to_one';r<-run();stopifnot(all(c('JOIN_CARDINALITY','JOIN_WEIGHT_MULTIPLICATION','JOIN_AMOUNT_MULTIPLICATION','RECONCILIATION_WEIGHT','RECONCILIATION_AMOUNT')%in%names(r$violation_counts)));nodes[[2]]$available_at<-'2024-01-03';nodes[[2]]$semantic_role<-'OUTCOME';r<-run();stopifnot(all(c('TRANSFORMATION_LOOKAHEAD','SOURCE_USE_LOOKAHEAD','OUTCOME_IN_PREDICTIVE_PATH')%in%names(r$violation_counts)));edges[[3]]<-list(parent_id='out',child_id='left');stopifnot(inherits(try(run(),silent=TRUE),'try-error'))
