fingerprint<-getFromNamespace('.cr_hash','creditratingsystem');e0<-list(event_id='e0',idempotency_key='k0',occurred_at='2024-01-01',known_at='2024-01-01',sequence=0,payload=list(balance=100),revision_of=NULL);e0$payload_hash<-fingerprint(e0$payload);e1<-list(event_id='e1',idempotency_key='k1',occurred_at='2024-01-01',known_at='2024-01-03',sequence=1,payload=list(balance=80),revision_of='e0');e1$payload_hash<-fingerprint(e1$payload);events<-list(e0,e0,e1);kinds<-c('MODEL','CALIBRATION','POLICY','SOURCE');snapshots<-lapply(seq_along(kinds),function(i)list(snapshot_id=kinds[i],kind=kinds[i],content_hash=hash(letters[i]),known_at='2023-12-01',effective_from='2023-12-01',effective_until=NULL));dates<-c('2024-01-02','2024-01-04');original<-lapply(1:2,function(i)list(checkpoint_id=paste0('c',i-1),as_of=dates[i],known_at=dates[i],event_log_hash=fingerprint(events),snapshot_hashes=setNames(lapply(snapshots,function(s)s$content_hash),kinds),applied_event_ids=if(i==1)list('e0')else list('e0','e1'),state=list(balance=if(i==1)100 else 80,approved=TRUE,path=list(1,2))));replay<-lapply(original,function(cp){cp$mode<-'REPLAY';cp});contract<-list(contract_id='replay',version='1',reference='append-only-unit-case',ordering='KNOWN_AT_SEQUENCE_EVENT_ID',idempotency='FIRST_IDENTICAL_DELIVERY',corrections='APPEND_REVISION',required_checkpoint_ids=c('c0','c1'),absolute_tolerance=1e-10,relative_tolerance=0);run<-function()replay_consistency(events,original,replay,snapshots,contract)$value;r<-run();stopifnot(r$decision$status=='PASS',r$metrics$duplicate_identical_deliveries==1,r$checkpoint_findings[[1]]$known_revision_count==0,r$checkpoint_findings[[2]]$known_revision_count==1,!r$event_execution_performed,!r$original_decisions_modified);replay[[2]]$state$balance<-80+1e-11;stopifnot(run()$decision$status=='PASS');replay[[1]]$applied_event_ids<-list('e0','e0','e1');replay[[1]]$state$balance<-80;replay[[2]]$mode<-'COUNTERFACTUAL';r<-run();stopifnot(all(c('EVENT_ORDER_OR_IDEMPOTENCY_MISMATCH','CHECKPOINT_STATE_MISMATCH','COUNTERFACTUAL_NOT_REPLAY')%in%names(r$violation_counts)));events[[2]]$payload$balance<-0;stopifnot(inherits(try(run(),silent=TRUE),'try-error'))
